import importlib
import pickle
import sys
import uuid
from datetime import UTC, datetime


class LegacyAnchor:
    def __init__(self):
        self.name = "legacy-migration-anchor"


ANCHOR = LegacyAnchor()


class ReplayProgram:
    @staticmethod
    def run(program):
        current = resolve_root(program.get("root", "anchor"))
        bound_owner = None
        for step in program.get("ops", []):
            if "attr" in step:
                bound_owner = current
                current = getattr(current, step["attr"])
                continue
            if "getitem" in step:
                bound_owner = None
                current = current[step["getitem"]]
                continue
            if "call_attr" in step:
                method = getattr(current, step["call_attr"])
                bound_owner = current
                current = method(*step.get("args", []))
                continue
            if "call" in step:
                called = current
                result = called(*step.get("call", []))
                if getattr(called, "__name__", "") == "read" and hasattr(bound_owner, "close"):
                    bound_owner.close()
                bound_owner = None
                current = result
                continue
            raise ValueError("unsupported replay operation")
        return current


class ArchiveSnapshot:
    reduce_mode = "safe"

    def __init__(self, owner, data):
        self.owner = owner
        self.data = data
        self.created_at = datetime.now(UTC).isoformat(timespec="seconds").replace("+00:00", "Z")

    @staticmethod
    def restore_safe(data):
        profile = data.get("profile", {})
        return {
            "status": "ok",
            "message": "Profile archive restored in preview mode.",
            "theme": profile.get("theme", "light"),
            "language": profile.get("language", "en"),
        }

    def __reduce__(self):
        if self.__class__.reduce_mode == "legacy_task":
            return (ReplayProgram.run, (self.data.get("program", {}),))
        return (ArchiveSnapshot.restore_safe, (self.data,))


def resolve_root(name):
    if name == "anchor":
        return ANCHOR
    if name in {"app.archive.ANCHOR", "shadow_archive.archive.ANCHOR"}:
        return ANCHOR

    parts = name.split(".")
    for idx in range(len(parts), 0, -1):
        module_name = ".".join(parts[:idx])
        try:
            module = importlib.import_module(module_name)
        except ImportError:
            continue
        current = module
        for attr in parts[idx:]:
            current = getattr(current, attr)
        return current
    raise ValueError("unknown replay root")


def make_archive_id():
    return uuid.uuid4().hex


def dumps_snapshot(snapshot):
    return pickle.dumps(snapshot, protocol=4)


def loaded_module_names():
