    if not isinstance(src, dict):
        return dst

    if isinstance(dst, dict):
        for key, value in src.items():
            if isinstance(value, dict) and key in dst:
                vulnerable_deep_merge(value, dst[key])
            else:
                dst[key] = value
        return dst

    for key, value in src.items():
        if isinstance(value, dict) and hasattr(dst, key):
            vulnerable_deep_merge(value, getattr(dst, key))
        else:
            setattr(dst, key, value)
    return dst


